-- Reset the shop catalogue to the team sheet (32 products). Generated from prototype/index.html (tools/build-shop-data.py output).
-- Run in Supabase -> SQL editor. It clears products, pairings, stock and product photo rows, then reloads them.
-- It does NOT touch orders, customers, coupons, gift cards, reviews, settings, site text or 'brand' photos.
begin;
delete from pairings;
delete from stock;
delete from products;
delete from media where product_id <> 'brand';
commit;
